export type PageKey = keyof typeof PAGE_TEXT;
export type HeaderKey = "documents" | "goals" | "learn" | "lifegraph" | "notifications" | "planning" | "profile" | "schemes" | "score" | "shield" | "accessibility";

/** Text for a language; falls back to English only if a translation is missing. */
export const tr = (lang: Lang, key: PageKey): string => PAGE_TEXT[key][lang] ?? PAGE_TEXT[key].en;

/** Like tr, with {name} placeholders filled in. Numbers and money are formatted by the caller (code), never translated. */
export const trf = (lang: Lang, key: PageKey, vars: Record<string, string | number>): string =>
  tr(lang, key).replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? ""));
